    manager.dropBaseSchema(conn);
    assertThat(meta.getTables(null, manager.getCatalogStore().getSchema().getSchemaName().toUpperCase(), null, new String[] { "TABLE" }), allOf(not(hasItemInResultSet("TESTTABLE1", "TABLE_NAME")), not(hasItemInResultSet("TESTTABLE2", "TABLE_NAME"))));
    ResultSet triggers = stmt.executeQuery("select a.TRIGGERNAME from SYS.SYSTRIGGERS a inner join SYS.SYSSCHEMAS b " + " on a.SCHEMAID = b.SCHEMAID where b.SCHEMANAME = '" + manager.getCatalogStore().getSchema().getSchemaName().toUpperCase() + "'");
    assertThat(triggers, not(hasItemInResultSet("TESTTRIGGER1", "TRIGGERNAME")));
    ResultSet views = stmt.executeQuery("select a.TABLENAME from SYS.SYSTABLES a inner join SYS.SYSSCHEMAS b " + " on a.SCHEMAID = b.SCHEMAID where a.TABLETYPE = 'V' and b.SCHEMANAME = '" + manager.getCatalogStore().getSchema().getSchemaName().toUpperCase() + "'");
    assertThat(views, not(hasItemInResultSet("TESTVIEW", "TABLENAME")));
}

