@Test
public void testToTimestamp() throws IOException {
    long expectedTimestamp = System.currentTimeMillis();
    TimestampDatum expected = DatumFactory.createTimestmpDatumWithUnixTime((int) (expectedTimestamp / 1000));
    // (expectedTimestamp / 1000) means the translation from millis seconds to unix timestamp
    String q1 = String.format("select to_timestamp(%d);", (expectedTimestamp / 1000));
    testSimpleEval(q1, new String[] { expected.toString() });
    testSimpleEval("select to_timestamp('1997-12-30 11:40:50.345', 'YYYY-MM-DD HH24:MI:SS.MS');", new String[] { "1997-12-30 11:40:50.345" });
    testSimpleEval("select to_timestamp('1997-12-30 11:40:50.345 PM', 'YYYY-MM-DD HH24:MI:SS.MS PM');", new String[] { "1997-12-30 23:40:50.345" });
    testSimpleEval("select to_timestamp('0097/Feb/16 --> 08:14:30', 'YYYY/Mon/DD --> HH:MI:SS');", new String[] { "0097-02-16 08:14:30" });
    testSimpleEval("select to_timestamp('97/2/16 8:14:30', 'FMYYYY/FMMM/FMDD FMHH:FMMI:FMSS');", new String[] { "0097-02-16 08:14:30" });
    testSimpleEval("select to_timestamp('1985 September 12', 'YYYY FMMonth DD');", new String[] { "1985-09-12 00:00:00" });
    testSimpleEval("select to_timestamp('1,582nd VIII 21', 'Y,YYYth FMRM DD');", new String[] { "1582-08-21 00:00:00" });
