@Test
public void testDateTimeNow() throws IOException {
    TimeZone originalTimezone = TimeZone.getDefault();
    TimeZone.setDefault(TimeZone.getTimeZone("GMT-6"));
    QueryContext context = new QueryContext(getConf());
    context.put(SessionVars.TIMEZONE, "GMT-6");
    try {
        Date expectedDate = new Date(System.currentTimeMillis());
        testSimpleEval(context, "select to_char(now(), 'yyyy-MM-dd');", new String[] { dateFormat(expectedDate, "yyyy-MM-dd") });
        testSimpleEval(context, "select cast(extract(year from now()) as INT4);", new String[] { dateFormat(expectedDate, "yyyy") });
        testSimpleEval(context, "select current_date();", new String[] { dateFormat(expectedDate, "yyyy-MM-dd") });
        testSimpleEval(context, "select cast(extract(hour from current_time()) as INT4);", new String[] { String.valueOf(Integer.parseInt(dateFormat(expectedDate, "HH"))) });
        expectedDate.setDate(expectedDate.getDate() + 1);
        testSimpleEval(context, "select current_date() + 1;", new String[] { dateFormat(expectedDate, "yyyy-MM-dd") });
    } finally {
        TimeZone.setDefault(originalTimezone);
    }
}

@Test
public void testTimeValueKeyword() throws IOException {
    TimeZone originTimeZone = TimeZone.getDefault();
    TimeZone.setDefault(TimeZone.getTimeZone("GMT-6"));
    QueryContext context = new QueryContext(getConf());
    context.put(SessionVars.TIMEZONE, "GMT-6");
    try {
        Date expectedDate = new Date(System.currentTimeMillis());
        testSimpleEval(context, "select to_char(current_timestamp, 'yyyy-MM-dd');", new String[] { dateFormat(expectedDate, "yyyy-MM-dd") });
        testSimpleEval(context, "select cast(extract(year from current_timestamp) as INT4);", new String[] { dateFormat(expectedDate, "yyyy") });
        testSimpleEval(context, "select current_date;", new String[] { dateFormat(expectedDate, "yyyy-MM-dd") });
        testSimpleEval(context, "select cast(extract(hour from current_time) as INT4);", new String[] { String.valueOf(Integer.parseInt(dateFormat(expectedDate, "HH"))) });
    } finally {
        TimeZone.setDefault(originTimeZone);
    }
}

