    TableProto proto = (TableProto) FileUtil.loadProto(cluster.getDefaultFileSystem(), metaPath, TableProto.getDefaultInstance());
    meta = new TableMeta(proto);
    FileFragment fragment = new FileFragment("test.tbl", dataPath, 0, file.getLen());
    int tupleCnt = 0;
    start = System.currentTimeMillis();
    Scanner scanner = TableSpaceManager.getFileStorageManager(conf).getScanner(meta, schema, fragment);
    scanner.init();
    while ((tuple = scanner.next()) != null) {
        tupleCnt++;
    }
    scanner.close();
    assertEquals(tupleNum, tupleCnt);
    tupleCnt = 0;
    long fileStart = 0;
    long fileLen = file.getLen() / 13;
    for (int i = 0; i < 13; i++) {
        fragment = new FileFragment("test.tbl", dataPath, fileStart, fileLen);
        scanner = new RowFile.RowFileScanner(conf, schema, meta, fragment);
        scanner.init();
        while ((tuple = scanner.next()) != null) {
            if (!idSet.remove(tuple.getInt4(0))) {
                System.out.println("duplicated! " + tuple.getInt4(0));
            }
            tupleCnt++;
        }
        scanner.close();
        fileStart += fileLen;
        if (i == 11) {
            fileLen = file.getLen() - fileStart;
        }
    }
    assertEquals(tupleNum, tupleCnt);
}

