    int columnNum = 11 + (handleProtobuf ? 1 : 0);
    VTuple seedTuple = new VTuple(columnNum);
    seedTuple.put(new Datum[] { // 0
    DatumFactory.createBool(true), // 2
    DatumFactory.createChar("hyunsik"), // 3
    DatumFactory.createInt2((short) 17), // 4
    DatumFactory.createInt4(59), // 5
    DatumFactory.createInt8(23l), // 6
    DatumFactory.createFloat4(77.9f), // 7
