        for (int j = 0; j < columnNum; j++) {
            if (i == j) {
                assertEquals(NullDatum.get(), retrieved.asDatum(j));
            } else {
                assertEquals(seedTuple.get(j), retrieved.asDatum(j));
            }
        }
        i++;
    }
    scanner.close();
}

